function avc(n){ var cs=['#0F8A5F','#0B6B4A','#2563EB','#7C3AED','#D97706','#0891B2'];var h=0;for(var i=0;i<(n||'').length;i++)h=(h*31+n.charCodeAt(i))%cs.length;return cs[h]; }
