  var a=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  var b=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  function tw(x){return x<20?a[x]:b[Math.floor(x/10)]+(x%10?' '+a[x%10]:'');}
  function conv(x){var s='';if(x>=1e7){s+=conv(Math.floor(x/1e7))+' Crore ';x%=1e7;}if(x>=1e5){s+=tw(Math.floor(x/1e5))+' Lakh ';x%=1e5;}if(x>=1e3){s+=tw(Math.floor(x/1e3))+' Thousand ';x%=1e3;}if(x>=100){s+=a[Math.floor(x/100)]+' Hundred ';x%=100;}if(x>0)s+=(s?'and ':'')+tw(x);return s.trim();}
  return conv(n)+' Rupees Only';
}

/* ── frappe.call promise wrapper ── */
function call(method,args){
  return new Promise(function(resolve,reject){

    /*
     * LIFE Billing Web Page runs inside Frappe Website.
     * Some late-loaded patches can execute while the global frappe
     * object exists but frappe.call has not yet been attached.
     *
     * Never throw "frappe.call is not a function".
     * Wait briefly for the real request API and then execute.
     */
    var attempts=0;
    var maxAttempts=80;

    function executeRequest(){

      attempts+=1;

      var frappeApi=
        window.frappe &&
        typeof window.frappe.call==='function'
          ? window.frappe
          : null;

      if(!frappeApi){

        if(attempts<maxAttempts){
          window.setTimeout(
            executeRequest,
            100
          );
          return;
        }

        reject({
          message:
            'Frappe request API is not ready. Please refresh the page and try again.'
        });

        return;
      }

      /* Button and page-local loaders show progress; avoid blocking the entire workspace. */

      frappeApi.call({
        method:method,
        args:args||{},

        callback:function(r){
          resolve(r&&r.message);
        },

        error:function(xhr){
          var e=xhr||{};

          try{
            if(xhr && xhr.responseJSON){

              if(xhr.responseJSON._server_messages){
                e._server_messages=
                  xhr.responseJSON._server_messages;
              }

              if(xhr.responseJSON.exception){
                e.exception=
                  xhr.responseJSON.exception;
              }

              if(xhr.responseJSON.exc){
                e.exc=
                  xhr.responseJSON.exc;
              }
            }
          }catch(_){}

          reject(e);
        }
      });
    }

    executeRequest();
  });
}
function getList(doctype,filters,fields,opts){
