var SCOPE='';
function initScope(){
  var s=_g('scope'); if(!s)return;

  /* A branch user (restricted by User Permission) may only ever see their
     own branch — no Head Office option, and nothing to choose. */
  if(!IS_HEAD_OFFICE && ALLOWED_BRANCHES.length){
    if(ALLOWED_BRANCHES.length===1){
      SCOPE=ALLOWED_BRANCHES[0];
      USER_BRANCH=SCOPE;
      s.innerHTML='<option value="'+esc(SCOPE)+'" selected>📍 '+esc(SCOPE)+' Branch</option>';
      s.disabled=true;
      s.style.cursor='default';
      s.title='You are signed in to the '+SCOPE+' branch';
      /* keep the branch list consistent everywhere else on the page */
      BRANCHES=[SCOPE];
      return;
    }
    /* a few branches allowed — offer only those, no Head Office */
    SCOPE = (ALLOWED_BRANCHES.indexOf(USER_BRANCH)>-1) ? USER_BRANCH : ALLOWED_BRANCHES[0];
    s.innerHTML=ALLOWED_BRANCHES.map(function(b){
      return '<option value="'+esc(b)+'"'+(b===SCOPE?' selected':'')+'>📍 '+esc(b)+' Branch</option>';
    }).join('');
    s.disabled=false;
    BRANCHES=ALLOWED_BRANCHES.slice();
    return;
  }

  /* Head Office / unrestricted user — full picker */
  s.disabled=false;
  s.innerHTML='<option value="">🏢 Head Office — All Branches</option>'+
    BRANCHES.map(function(b){return '<option value="'+esc(b)+'"'+(b===USER_BRANCH?' selected':'')+'>📍 '+esc(b)+' Branch</option>';}).join('');
  if(USER_BRANCH){ SCOPE=USER_BRANCH; }
}
