var CUR=null, CUR_P=null, CUR_INVS=[];
function valStatus(inv){
  var t=today();
  if(!inv.expiry) return {k:'valid',lbl:'—',cls:'bg-grey'};
  if(t<=inv.expiry)return {k:'valid',lbl:'Valid till '+fmtD(inv.expiry),cls:'bg-green'};
  if(t<=inv.graceEnd)return {k:'grace',lbl:'⏰ Grace till '+fmtD(inv.graceEnd),cls:'bg-amber'};
  return {k:'locked',lbl:'🔒 Execution Locked',cls:'bg-red'};
}
function addDays(d,n){ var x=new Date(d); x.setDate(x.getDate()+n); return x.toISOString().split('T')[0]; }

function openSummary(pid){
