    var kbar=
      '<div class="kpi-row" style="margin:14px 0">'+
        '<div class="kpi kpi-blue"><div class="kpi-val">'+fmtI(billed)+'</div><div class="kpi-lbl">Lifetime Billed</div></div>'+
        '<div class="kpi kpi-green"><div class="kpi-val">'+fmtI(paid)+'</div><div class="kpi-lbl">Lifetime Paid</div></div>'+
        '<div class="kpi kpi-red"><div class="kpi-val">'+fmtI(due)+'</div><div class="kpi-lbl">Outstanding</div><div class="kpi-sub">'+dueInvs.length+' open bill(s)</div></div>'+
        '<div class="kpi kpi-amber"><div class="kpi-val">'+invs.length+'</div><div class="kpi-lbl">Total Invoices</div></div>'+
      '</div>';

    var dueStrip = due>0 ?
