      '<button class="btn btn-red btn-sm" id="cs-collect-all">💰 Collect a due</button></div>' : '';

    var invRows = invs.length ? invs.map(function(i){
      var st=i.status||'';
      var badge = (i.outstanding_amount<=0)?'bg-green':(i.outstanding_amount<i.grand_total?'bg-amber':'bg-red');
      return '<div class="inv-row" data-inv="'+esc(i.name)+'">'+
        '<div class="inv-head">'+
          '<span class="chev">▶</span>'+
          '<div style="flex:1;min-width:150px"><b style="color:var(--g0)">'+esc(i.name)+'</b>'+(i.custom_therapy_plan?' <span class="badge bg-purple" style="font-size:8.5px">TP</span>':'')+
            '<div style="font-size:10.5px;color:var(--txt4)">'+fmtD(i.posting_date)+' · '+esc(i.branch||'')+'</div></div>'+
          '<span class="money">'+fmtM(i.grand_total)+'</span>'+
