    var rf=_g('cs-refresh'); if(rf)rf.onclick=function(){ openSummary(pid); };
    var ca=_g('cs-collect-all'); if(ca)ca.onclick=function(){ if(dueInvs[0])openCollect(dueInvs[0].name); };
    _all('[data-collect]').forEach(function(b){ b.onclick=function(e){ e.stopPropagation(); openCollect(this.getAttribute('data-collect')); }; });
    _all('.inv-row').forEach(function(row){
      row.querySelector('.inv-head').onclick=function(){
        row.classList.toggle('open');
        if(row.classList.contains('open')){ loadInvBody(row.getAttribute('data-inv')); }
