  var key=loanRows.map(function(r){return r.i+':'+r.mode;}).join('|');
  if(lb.getAttribute('data-key')===key) return;
  lb.setAttribute('data-key',key);
  lb.style.display='block';
  lb.innerHTML=loanRows.map(function(r){
    var under = r.amount>0 && r.amount<LOAN_MIN;
    return '<div style="border:1.5px solid #C4B5FD;background:#F5F3FF;border-radius:10px;padding:14px;margin-bottom:10px">'+
