      (under
        ? '<div style="font-size:12px;font-weight:700;color:var(--red);margin-bottom:8px">⚠️ Loan modes need at least '+fmtM(LOAN_MIN)+' on this row (currently '+fmtM(r.amount)+').</div>'
        : '<div style="font-size:12px;color:var(--txt3);margin-bottom:10px">Amount on this row: <b>'+fmtM(r.amount)+'</b></div>')+
