  var ok=false;
  try{ ok=document.execCommand('copy'); }catch(e){}
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(t.value).then(function(){ alertMsg('Payment link copied.','green'); }).catch(function(){});
  } else {
