  var tc=_g('bl-tpl-clear'); if(tc)tc.onclick=function(){
    BILL.lines=[]; BILL.pkg_price=0; BILL.pkg_name=''; BILL.pkg_tc='';
    var tplSel=_g('bl-template'); if(tplSel)tplSel.value='';
    var n=_g('bl-target-note'); if(n)n.innerHTML='';
    _g('bl-lines').innerHTML=''; addLine(); recalc();
    alertMsg('Therapy lines and template selection cleared.','green');
  };

  (function(){
    var hasPaid=(CUR_INVS||[]).some(function(i){ return ['Paid','Partly Paid','Overdue'].indexOf(i.status)>-1; });
    var ms=_g('bl-media'), note=_g('bl-media-note');
    if(ms){
      if(hasPaid){ ms.value='Existing Customer'; ms.disabled=true; if(note)note.innerHTML='🔒 Existing client (has paid bills) → source locked to <b>Existing Customer</b>.'; }
      else { ms.disabled=false; if(note)note.innerHTML='New client → pick how they came in (Call Center / Reference / Direct Walk-in).'; }
    }
  })();

  addLine();
