    openBill(inv); updateApprBadge();
    try{ renderApprovals(); }catch(_){}
    refreshBillLists();
  }).catch(function(e){
    busyDone();
    if(e && e.message==='cancelled') return;
    alertMsg('Reject failed: '+serverErr(e),'red');
  });
}
function submitBill(inv){
