/* ══════════════════════════════════════════════════════════════════
   PACKAGE-ONLY THERAPIES — billable only inside a package / template
   ══════════════════════════════════════════════════════════════════ */
var PACKAGE_ONLY_PREFIXES = [
  'LIFErise',     // LIFErise P1/P2/P3 components + LIFErise Online items
  'IH'            // "IH — …" / "IH - …" in-house package components
];
var PACKAGE_ONLY_SUFFIXES = ['-SLE','-AAGE'];
var PACKAGE_ONLY_THERAPIES = [
  // exact therapy names, e.g. 'Diet Counselling',
];
function isPackageOnly(name){
  if(!name) return false;
  var n=String(name).trim().toLowerCase();
  for(var p=0;p<PACKAGE_ONLY_PREFIXES.length;p++){
    var pre=String(PACKAGE_ONLY_PREFIXES[p]).trim().toLowerCase();
    if(pre && (n===pre || n.indexOf(pre+' ')===0 || n.indexOf(pre+'-')===0 ||
               n.indexOf(pre+' —')===0 || n.indexOf(pre+' -')===0)) return true;
  }
  for(var sfx=0;sfx<PACKAGE_ONLY_SUFFIXES.length;sfx++){
    var suf=String(PACKAGE_ONLY_SUFFIXES[sfx]).trim().toLowerCase();
    if(suf && n.length>=suf.length && n.slice(-suf.length)===suf) return true;
  }
  for(var i=0;i<PACKAGE_ONLY_THERAPIES.length;i++){
    if(String(PACKAGE_ONLY_THERAPIES[i]).trim().toLowerCase()===n) return true;
  }
  for(var c=0;c<CATALOG.length;c++){
    if(CATALOG[c].n && CATALOG[c].n.toLowerCase()===n) return CATALOG[c].pkg_only===1;
  }
  return false;
}

/* Healthcare Practitioner picker, filtered by the selected billing branch. */
function wirePractitionerSearch(){
  var inp=_g('bl-prac-search'), dd=_g('bl-prac-dd'),
      hid=_g('bl-practitioner'), pick=_g('bl-prac-pick');
  if(!inp||!dd)return;
  function render(){
    var q=(inp.value||'').trim().toLowerCase();
    var br=_v('bl-branch')||BILL.branch||'';
    var list=(PRACTITIONERS||[]).filter(function(p){ return !br || p.branch===br; });
    list=dedupePractitioners(list);
    if(q) list=list.filter(function(p){ return (p.practitioner_name||'').toLowerCase().indexOf(q)>-1; });
    list=list.slice(0,50);
    dd.innerHTML = list.length
      ? list.map(function(p){
          return '<div class="tp-dd-item" data-id="'+esc(p.name)+'" data-n="'+esc(p.practitioner_name||'')+'">'+
            '<span>'+esc(p.practitioner_name||p.name)+'</span></div>';
        }).join('')
      : '<div class="tp-dd-item">'+(br?('No practitioner mapped to '+esc(br)):'No practitioner found')+'</div>';
    dd.classList.add('show');
    dd.querySelectorAll('[data-id]').forEach(function(el){
      el.onclick=function(){
        if(hid)hid.value=this.getAttribute('data-id');
        inp.value=this.getAttribute('data-n');
        if(pick)pick.innerHTML='✔ '+esc(this.getAttribute('data-n'));
        dd.classList.remove('show');
      };
    });
  }
  inp.oninput=function(){ if(hid)hid.value=''; if(pick)pick.innerHTML=''; render(); };
  inp.onfocus=render;
}

