function doApprove(i){

  var r=APPR_ROWS[i];

  if(!r){
    return;
  }

  var inv=r.linked_invoice;

  if(!inv){
    apprErr(
      'Sales Invoice could not be identified.'
    );
    return;
  }

  Promise.all([
    getDoc(
      'Sales Invoice',
      inv
    ),
    lifeLoadInvoiceDiscountRequests(
      inv
    )
  ])

  .then(function(res){

    BILL_DOC=res[0] || {name:inv};
    BILL_REQS=res[1] || [];

    /*
     * Safety fallback: ensure the clicked request remains actionable
     * even if an older bootstrap/direct permission path omitted it.
     */
    var found=false;

    (BILL_REQS||[]).forEach(function(row){
      if(row && row.name===r.name){
        found=true;
      }
    });

    if(!found){
      BILL_REQS.push(r);
    }

    billApprove(
      r.name
    );

  })

  .catch(function(e){

    apprErr(
      'Could not load invoice before approval: '+
      serverErr(e)
    );

  });

}
