/* ================================================================
   FIXED CASCADING DISCOUNT
   L1 / L2 / L3 percentages are ALWAYS based on ORIGINAL BILL BASE.
   5% + 5% + 5% = exactly 15%.
   ================================================================ */

var CASCADE_CAP_PCT = 15;

function requestNextApproval(inv){

  if(!inv){
    return;
  }


  var _si=null;
  var _reqs=[];


  /* ============================================================
     LOAD INVOICE
     ============================================================ */

  getDoc(
    'Sales Invoice',
    inv
  )

  .then(function(si){


    if(!si){

      throw new Error(
        'Sales Invoice could not be loaded.'
      );

    }


    if(si.docstatus!==0){

      alertMsg(
        'This bill is already submitted. '+
        'Discount can only be requested while Draft.',
        'red'
      );

      return Promise.reject({
        message:'cancelled'
      });

    }


    _si=si;


    return getList(

      'Discount Approval Request',

      [
        ['linked_invoice','=',inv]
      ],

      [
        'name',
        'selected_approver',
        'requested_by',
        'status',
        'approval_level',
        'bill_total',
        'requested_discount_pct',
        'approved_discount_pct',
        'requested_final_amount',
        'approved_final_amount',
        'approved_by',
        'approved_at',
        'creation',
        'linked_invoice'
      ],

      {
        limit:0,
        order_by:'creation asc'
      }

    );

  })


  /* ============================================================
     EXISTING APPROVALS
     ============================================================ */

  .then(function(reqs){


    _reqs=reqs||[];


    var anyPending=
      _reqs.some(function(r){
        return r.status==='Pending';
      });


    if(anyPending){

      alertMsg(
        'A discount request is already Pending. '+
        'Approve or reject it first.',
        'red'
      );

      return Promise.reject({
        message:'cancelled'
      });

    }


    /* ==========================================================
       USED LEVELS
       ========================================================== */

    var usedLevels={};
    var usedApprovers={};


    _reqs.forEach(function(r){

      if(
        r.status==='Pending' ||
        r.status==='Approved'
      ){

        if(r.approval_level){

          usedLevels[
            r.approval_level
          ]=true;

        }


        if(r.selected_approver){

          usedApprovers[
            r.selected_approver
          ]=true;

        }

      }

    });


    /* ==========================================================
       FIXED ORIGINAL GRAND TOTAL INCLUDING GST

       Never use the invoice's current grand_total after an approval because
       that value is already discounted. The first approval request stores
       the permanent GST-inclusive base in bill_total.
       ========================================================== */

    var orig=0;

    _reqs.forEach(function(r){
      if(!(orig>0)){
        var stored=parseFloat(r.bill_total||0);
        if(stored>0)orig=stored;
      }
    });

    /* Fallback only for an invoice that has no earlier approval request. */
    if(!(orig>0)){
      orig=parseFloat(
        _si.grand_total ||
        _si.rounded_total ||
        0
      );
    }


    if(!(orig>0)){

      alertMsg(
        'Original Grand Total including GST could not be identified.',
        'red'
      );

      return Promise.reject({
        message:'cancelled'
      });

    }


    /*
     * L4 amount includes GST, so its upper limit is the current
     * invoice GRAND TOTAL, not the original Grand Total including GST.
     */
    var currentGrand=parseFloat(
      _si.grand_total ||
      0
    );


    /* ==========================================================
       APPROVED NORMAL %
       ========================================================== */

    var approvedPct=0;


    _reqs.forEach(function(r){

      if(r.status!=='Approved'){
        return;
      }


      var lvl=
        r.approval_level || 'L1';


      if(lvl==='L4'){
        return;
      }


      var p=parseFloat(

        r.requested_discount_pct ||

        r.approved_discount_pct ||

        0

      );


      if(p>0){
        approvedPct+=p;
      }

    });


    approvedPct=
      Math.round(
        approvedPct*100
      )/100;


    var siPct=parseFloat(
      _si.total_approver_discount_pct || 0
    );


    if(
      siPct>approvedPct &&
      siPct<=CASCADE_CAP_PCT
    ){

      approvedPct=siPct;

    }


    var approvedAmount=
      Math.round(
        orig*approvedPct
      )/100;


    var currentTaxable=
      Math.round(
        (
          orig-approvedAmount
        )*100
      )/100;


    var avail=
      Math.round(
        (
          CASCADE_CAP_PCT-approvedPct
        )*100
      )/100;


    if(avail<0){
      avail=0;
    }


    /* ==========================================================
       APPROVER OPTIONS
       ========================================================== */

    var opts=[];


    if(
      !usedLevels.L1 &&
      !usedApprovers[CURRENT_USER] &&
      avail>0
    ){

      opts.push({

        value:
          CURRENT_USER,

        label:
          CURRENT_USER+
          ' · L1 · Branch Level'

      });

    }


    (APPROVERS||[]).forEach(function(a){


      if(
        !a ||
        !a.user
      ){
        return;
      }


      if(a.user===CURRENT_USER){
        return;
      }


      var lvl=
        a.approval_level || 'L1';


      /*
       * One approval per LEVEL.
       */
      if(usedLevels[lvl]){
        return;
      }


      if(usedApprovers[a.user]){
        return;
      }


      /*
       * After 15% only L4.
       */
      if(
        avail<=0 &&
        lvl!=='L4'
      ){
        return;
      }


      opts.push({

        value:
          a.user,

        label:
          (
            a.full_name ||
            a.user
          )+
          ' · '+
          lvl+
          (
            a.designation
              ? ' · '+a.designation
              : ''
          )

      });

    });


    if(!opts.length){

      alertMsg(
        'No further discount approval level is available.',
        'amber'
      );

      return Promise.reject({
        message:'cancelled'
      });

    }


    opts.unshift({

      value:'',
      label:'— Select approver —'

    });


    /* ==========================================================
       DIALOG
       ========================================================== */

    return uiDialog({

      title:
        '🔐 Request Discount Approval',

      subtitle:
        'L1 / L2 / L3 can approve up to 5% each. '+
        'All percentages are based on the original Grand Total including GST.',

      info:

        '<b>'+esc(inv)+'</b>'+

        '<br>Original Grand Total including GST: <b>'+
        fmtM(orig)+
        '</b>'+

        '<br>Already approved: <b>'+
        approvedPct+
        '%</b> = '+
        '<b style="color:var(--red)">− '+
        fmtM(approvedAmount)+
        '</b>'+

        '<br>Current payable including GST: '+
        '<b style="color:var(--g1)">'+
        fmtM(currentTaxable)+
        '</b>'+

        '<br>Normal approval remaining: <b>'+
        avail+
        '%</b>',


      fields:[


        /* APPROVER */

        {

          name:'approver',
          label:'Approver',
          type:'select',
          options:opts,
          required:true,


          live:function(val){


            var lvl='';


            if(val===CURRENT_USER){
              lvl='L1';
            }


            (APPROVERS||[]).forEach(function(a){

              if(a.user===val){

                lvl=
                  a.approval_level ||
                  'L1';

              }

            });


            var pctInput=
              _g('dlgf-1');

            var finalInput=
              _g('dlgf-2');


            var pctWrap=
              pctInput
                ? pctInput.parentElement
                : null;


            var finalWrap=
              finalInput
                ? finalInput.parentElement
                : null;


            if(!val){

              if(pctWrap){
                pctWrap.style.display='none';
              }

              if(finalWrap){
                finalWrap.style.display='none';
              }

              if(pctInput){
                pctInput.value='';
              }

              if(finalInput){
                finalInput.value='';
              }

              return '';
            }


            if(lvl==='L4'){

              if(pctWrap){
                pctWrap.style.display='none';
              }

              if(finalWrap){
                finalWrap.style.display='';
              }

              if(pctInput){
                pctInput.value='';
              }

            }

            else{

              if(pctWrap){
                pctWrap.style.display='';
              }

              if(finalWrap){
                finalWrap.style.display='none';
              }

              if(finalInput){
                finalInput.value='';
              }

            }


            return '';

          }

        },


        /* PERCENTAGE */

        {

          name:'pct',
          label:'Discount %',
          type:'number',
          placeholder:'e.g. 5',

          hint:
            'Calculated from original Grand Total including GST '+
            fmtM(orig)+'.',


          live:function(val,el){


            var p=
              parseFloat(
                val || 0
              );


            var cap=
              Math.min(
                5,
                avail
              );


            if(p>cap){

              p=cap;
              el.value=cap;

            }


            if(p<0){

              p=0;
              el.value=0;

            }


            if(!(p>0)){

              return (
                'Enter up to <b>'+
                cap+
                '%</b>.'
              );

            }


            var thisDisc=
              Math.round(
                orig*p
              )/100;


            var totalPct=
              Math.round(
                (
                  approvedPct+p
                )*100
              )/100;


            var totalDisc=
              Math.round(
                orig*totalPct
              )/100;


            var after=
              Math.round(
                (
                  orig-totalDisc
                )*100
              )/100;


            return (

              '<b>'+
              p+
              '%</b> = '+
              '<b style="color:var(--red)">− '+
              fmtM(thisDisc)+
              '</b>'+

              '<br>Total approved: <b>'+
              totalPct+
              '%</b> = '+
              '<b style="color:var(--red)">− '+
              fmtM(totalDisc)+
              '</b>'+

              '<br>Payable including GST after discount: '+
              '<b style="color:var(--g1)">'+
              fmtM(after)+
              '</b>'

            );

          }

        },


        /* L4 */

        {

          name:'final_amount',

          label:
            'Final invoice amount including GST — L4 / MD only ₹',

          type:'number',

          placeholder:
            'Final invoice amount including GST approved by MD'

        },


        /* REASON */

        {

          name:'reason',
          label:'Reason',
          type:'textarea',
          required:true

        }

      ],


      okLabel:
        'Send for approval',


      validate:function(v){


        var lvl='L1';


        if(v.approver===CURRENT_USER){
          lvl='L1';
        }


        (APPROVERS||[]).forEach(function(a){

          if(a.user===v.approver){

            lvl=
              a.approval_level ||
              'L1';

          }

        });


        if(usedLevels[lvl]){

          return (
            lvl+
            ' approval is already used for this bill.'
          );

        }


        var p=
          parseFloat(
            v.pct || 0
          );


        var fa=
          parseFloat(
            v.final_amount || 0
          );


        if(lvl==='L4'){

          if(!(fa>0)){

            return (
              'L4 / MD must enter the final invoice amount including GST.'
            );

          }


          if(
            currentGrand>0 &&
            fa>=currentGrand
          ){

            return (
              'Final invoice amount must be less than the current invoice total '+
              fmtM(currentGrand)+
              '.'
            );

          }

        }

        else{

          if(!(p>0)){

            return (
              'Enter a discount percentage.'
            );

          }


          if(avail<=0){

            return (
              'Normal 15% approval limit is exhausted. '+
              'Use L4 / MD.'
            );

          }


          var cap=
            Math.min(
              (
                LEVEL_INFO[lvl] ||
                {}
              ).max || 5,
              avail
            );


          if(p>cap){

            return (
              lvl+
              ' can approve at most '+
              cap+
              '%.'
            );

          }

        }


        return '';

      }

    })

    .then(function(v){

      return {
        values:v,
        orig:orig
      };

    });

  })


  /* ============================================================
     SEND REQUEST
     ============================================================ */

  .then(function(ctx){


    if(!ctx){
      return;
    }


    var v=ctx.values;
    var orig=ctx.orig;


    var lvl='L1';


    if(v.approver===CURRENT_USER){
      lvl='L1';
    }


    (APPROVERS||[]).forEach(function(a){

      if(a.user===v.approver){

        lvl=
          a.approval_level ||
          'L1';

      }

    });


    var isL4=
      lvl==='L4';


    var normalPct=
      isL4
        ? 0
        : parseFloat(
            v.pct || 0
          );


    var finalAmount=
      isL4
        ? parseFloat(
            v.final_amount || 0
          )
        : 0;


    /* ----------------------------------------------------------
       Find underlying Request Discount button.
       Dialog is closed now, so user sees spinner there.
       ---------------------------------------------------------- */

    var requestBtn=null;


    try{

      var buttons=
        ROOT.querySelectorAll(
          '#bill-actions button'
        );


      Array.prototype.forEach.call(
        buttons,
        function(b){

          var oc=
            b.getAttribute('onclick') || '';

          if(
            oc.indexOf(
              'requestNextApproval'
            )>=0
          ){

            requestBtn=b;

          }

        }
      );

    }catch(_){}


    var restoreRequest=
      btnBusy(
        requestBtn,
        'Sending…'
      );


    return call(

      'create_discount_approval_request',

      {

        invoice_name:
          inv,

        selected_approver:
          v.approver,

        approval_level:
          lvl,

        requested_discount_pct:
          normalPct,

        requested_final_amount:
          finalAmount,

        reason:
          v.reason

      }

    )

    .then(function(data){


      if(restoreRequest){
        restoreRequest();
        restoreRequest=null;
      }


      data=data||{};


      BILL_REQS=
        BILL_REQS || [];


      var requestedPct=
        normalPct;


      if(isL4){

        requestedPct=
          orig>0
            ? Math.round(
                (
                  (
                    orig-finalAmount
                  ) /
                  orig *
                  100
                ) *
                100
              ) / 100
            : 0;

      }


      BILL_REQS.push({

        name:
          data.request_name || '',

        linked_invoice:
          inv,

        requested_by:
          CURRENT_USER,

        selected_approver:
          v.approver,

        bill_total:
          orig,

        approval_level:
          lvl,

        status:
          'Pending',

        requested_discount_pct:
          requestedPct,

        requested_final_amount:
          isL4
            ? finalAmount
            : 0,

        approved_discount_pct:
          0,

        approved_final_amount:
          0,

        approved_by:
          '',

        approved_at:
          '',

        creation:
          new Date().toISOString()

      });


      if(BILL_DOC){

        BILL_DOC.discount_locked=1;

        BILL_DOC.approval_workflow_status=
          'Pending Approval';

        BILL_DOC.original_bill_total=
          orig;

      }


      renderBillDrawer();


      alertMsg(

        v.approver===CURRENT_USER

          ? 'Request raised — approve it from this bill.'

          : (
              'Approval request sent to '+
              v.approver+
              '.'
            ),

        'green'

      );


      try{
        updateApprBadge();
      }catch(_){}


      try{
        renderApprovals();
      }catch(_){}


      return data;

    })

    .catch(function(e){


      if(restoreRequest){
        restoreRequest();
        restoreRequest=null;
      }


      throw e;

    });

  })


  /* ============================================================
     ERROR
     ============================================================ */

  .catch(function(e){


    if(
      e &&
      e.message==='cancelled'
    ){
      return;
    }


    alertMsg(
      'Discount request failed: '+
      serverErr(e),
      'red'
    );

  });

}

function nowStamp(){
  try{ if(typeof frappe!=='undefined' && frappe.datetime && frappe.datetime.now_datetime) return frappe.datetime.now_datetime(); }catch(e){}
  var d=new Date();
  function p(n){return n<10?'0'+n:''+n;}
  return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());
}

