function showGenErr(msg){
  var box=_g('pv-err');
  if(box){ box.innerHTML='⚠️ '+esc(msg); box.style.display='block'; }
  toast(msg,'red');
}
function confirmGenerate(){

  var lines=currentLines();

  if(!lines.length){
    showGenErr('Add at least one therapy line');
    return;
  }


  var payload=billPayload();

  var wantDisc=
    payload.draft_only===1;


  /*
   * Always create invoice as Draft.
   */
  payload.draft_only=1;


  var eb=_g('pv-err');

  if(eb){
    eb.innerHTML='';
    eb.style.display='none';
  }


  /* ============================================================
     PACKAGE VALIDATION
     ============================================================ */

  if(BILL_MODE!=='package'){

    var blocked=lines.filter(function(l){
      return isPackageOnly(l.therapy);
    });

    if(blocked.length){

      showGenErr(
        blocked[0].therapy+
        ' can only be billed as part of a package — '+
        'switch to Package / Template.'
      );

      return;
    }
  }


  /* ============================================================
     SOURCE VALIDATION
     ============================================================ */

  if(!payload.practitioner){

    showGenErr(
      'Select a Consultant Employee before generating the bill.'
    );

    var consultantInput=_g('bl-prac-search');
    if(consultantInput){ consultantInput.focus(); consultantInput.setAttribute('aria-invalid','true'); }
    return;
  }

  var consultantSearch=_g('bl-prac-search');
  if(consultantSearch) consultantSearch.removeAttribute('aria-invalid');

  if(!payload.plan_media){

    showGenErr(
      'Select the Source / Media '+
      '(Call Center / Reference / Direct Walk-in / Existing Customer)'
    );

    return;
  }


  if(payload.plan_media==='Reference'){

    var rc=_g('bl-ref-isclient');
    var re=_g('bl-ref-isemp');

    var anyRef=
      (rc&&rc.checked) ||
      (re&&re.checked);


    if(!anyRef){

      showGenErr(
        'Source is Reference — tick whether it came '+
        'from a client or an employee'
      );

      return;
    }


    if(
      rc &&
      rc.checked &&
      !payload.reference_client
    ){

      showGenErr(
        'Pick the referring client from the search list'
      );

      return;
    }


    if(
      re &&
      re.checked &&
      !payload.reference_employee
    ){

      showGenErr(
        'Select the referring employee'
      );

      return;
    }

  }


  /* ============================================================
     INCENTIVE VALIDATION
     ============================================================ */

  if(
    payload.sharing_incentive &&
    !payload.incentive_employee
  ){

    showGenErr(
      'Sharing Incentive is ticked — select the incentive employee'
    );

    return;
  }


  /* ============================================================
     DISCOUNT VALIDATION
     ============================================================ */

  if(wantDisc){

    if(!payload.discount_approver){

      showGenErr(
        'Select an approver for the discount'
      );

      return;
    }


    if(!payload.discount_reason){

      showGenErr(
        'Enter a reason for the discount'
      );

      return;
    }


    if(
      !(payload.discount_pct>0) &&
      !(payload.discount_final_amount>0)
    ){

      showGenErr(
        'Enter a discount % or an L4 final amount'
      );

      return;
    }


    if(
      payload.discount_approver===CURRENT_USER &&
      payload.discount_pct>5
    ){

      showGenErr(
        'You can self-approve up to 5% only — '+
        'choose a higher approver for '+
        payload.discount_pct+
        '%'
      );

      return;
    }

  }


  /* ============================================================
     BUTTONS
     ============================================================ */

  var gen=_g('bl-generate');

  var pvBtn=
    _q('#m-preview .btn-green');


  var mainBtn=
    pvBtn || gen;


  /*
   * Mild button spinner only.
   */
  var restoreCreate=
    btnBusy(
      mainBtn,
      wantDisc
        ? 'Creating draft…'
        : 'Generating…'
    );


  if(gen && gen!==mainBtn){
    gen.disabled=true;
  }


  /* ============================================================
     CREATE PLAN + INVOICE
     ============================================================ */

  call(
    'lifescc.billing.create_plan_and_invoice_TEST',
    payload
  )

  .then(function(res){


    if(restoreCreate){
      restoreCreate();
      restoreCreate=null;
    }


    if(gen){
      gen.disabled=false;
    }


    if(
      !res ||
      !res.sales_invoice
    ){

      showGenErr(
        (
          res &&
          res.error
        )
        ||
        'Generation failed — check therapy rates / permissions'
      );

      return;
    }


    /* ==========================================================
       WITHOUT DISCOUNT
       ========================================================== */

    if(!wantDisc){

      finishGenerate(
        res,
        gen,
        pvBtn
      );

      return;
    }


    /* ==========================================================
       DISCOUNT FLOW
       ========================================================== */

    var inv=
      res.sales_invoice;


    var bt=parseFloat(
      res.subtotal ||
      res.total ||
      res.grand_total ||
      0
    );

    /*
     * L4 input means FINAL GRAND TOTAL INCLUDING GST.
     * Keep the invoice grand total separately from taxable base.
     */
    var originalGrand=parseFloat(
      res.grand_total ||
      0
    );


    if(!(bt>0)){

      showGenErr(
        'Draft '+inv+
        ' was created, but original Grand Total including GST '+
        'could not be identified.'
      );

      openBill(inv);

      return;
    }


    /* ==========================================================
       APPROVAL LEVEL
       ========================================================== */

    var appLevel='';

    var sel=
      _g('bl-disc-approver');


    if(
      sel &&
      sel.selectedOptions &&
      sel.selectedOptions[0]
    ){

      appLevel=
        sel.selectedOptions[0]
          .getAttribute('data-level')
        || '';

    }


    /*
     * Fallback from loaded Approver Master.
     */
    if(!appLevel){

      (APPROVERS||[]).forEach(function(a){

        if(
          a.user===
          payload.discount_approver
        ){

          appLevel=
            a.approval_level ||
            'L1';

        }

      });

    }


    if(
      payload.discount_approver===
      CURRENT_USER &&
      !appLevel
    ){

      appLevel='L1';

    }


    if(
      ['L1','L2','L3','L4']
        .indexOf(appLevel)<0
    ){

      appLevel='L1';

    }


    var isL4=
      appLevel==='L4';


    var pct=
      parseFloat(
        payload.discount_pct || 0
      );


    var finalAmount=
      parseFloat(
        payload.discount_final_amount || 0
      );


    /* ==========================================================
       L4 VALIDATION
       ========================================================== */

    if(isL4){

      if(!(finalAmount>0)){

        showGenErr(
          'L4 / MD must enter the final invoice amount including GST.'
        );

        return;
      }


      if(
        originalGrand>0 &&
        finalAmount>=originalGrand
      ){

        showGenErr(
          'L4 final invoice amount must be less than the current invoice total '+
          fmtM(originalGrand)+
          '.'
        );

        return;
      }

    }


    /* ==========================================================
       MILD SECOND STAGE LOADER
       ========================================================== */

    var restoreApproval=
      btnBusy(
        mainBtn,
        'Sending approval…'
      );


    if(gen && gen!==mainBtn){
      gen.disabled=true;
    }


    /* ==========================================================
       SINGLE APPROVAL CREATION API
       ========================================================== */

    return call(

      'create_discount_approval_request',

      {

        invoice_name:
          inv,

        selected_approver:
          payload.discount_approver,

        approval_level:
          appLevel,

        requested_discount_pct:
          isL4
            ? 0
            : pct,

        requested_final_amount:
          isL4
            ? finalAmount
            : 0,

        reason:
          payload.discount_reason

      }

    )

    .then(function(apprRes){


      if(restoreApproval){
        restoreApproval();
        restoreApproval=null;
      }


      if(gen){
        gen.disabled=false;
      }


      closeM(
        'm-preview'
      );


      var approvalText='';


      if(
        payload.discount_approver===
        CURRENT_USER
      ){

        approvalText=
          isL4
            ? (
                'L4 approval request created. '+
                'Approve it from the bill below.'
              )
            : (
                'Approve the '+
                pct+
                '% discount from the bill below.'
              );

      }

      else{

        approvalText=
          'Discount request sent to '+
          payload.discount_approver+
          ' — the bill stays locked until approval.';

      }


      alertMsg(

        'Draft '+
        inv+
        ' created. '+
        approvalText,

        'green',
        true

      );


      try{
        renderKPIs();
      }catch(_){}


      try{
        updatePendBadge();
      }catch(_){}


      try{
        updateApprBadge();
      }catch(_){}


      openBill(inv);


      return apprRes;

    })

    .catch(function(e){


      if(restoreApproval){
        restoreApproval();
        restoreApproval=null;
      }


      if(gen){
        gen.disabled=false;
      }


      showGenErr(

        'Draft '+
        inv+
        ' was created, but the discount request failed: '+
        serverErr(e)+
        ' — you can raise it from the bill screen.'

      );


      openBill(inv);

    });

  })


  /* ============================================================
     GENERATION ERROR
     ============================================================ */

  .catch(function(e){


    if(restoreCreate){
      restoreCreate();
      restoreCreate=null;
    }


    if(gen){
      gen.disabled=false;
    }


    showGenErr(
      'Generate failed: '+
      serverErr(e)
    );

  });

}
function finishGenerate(res,gen,pvBtn){
  [gen,pvBtn].forEach(function(b){ if(b){b.disabled=false;} });
  if(pvBtn)pvBtn.textContent='✅ Confirm & Generate Invoice';
  closeM('m-preview');
  alertMsg('Draft bill '+res.sales_invoice+' created for '+(BILL.client.patient_name||'')+
           ' — '+fmtM(res.grand_total)+'. Submit it, then collect the payment.','green',true);
  renderKPIs(); updatePendBadge();
  openBill(res.sales_invoice);
}

/* ════════════════ RECENT BILLS ════════════════ */
var REC_PAGE=1;
var REC_PER_PAGE=20;
function recentShiftDate(value,days){
  var d=new Date(String(value)+'T00:00:00');
  d.setDate(d.getDate()+days);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function setRecentPreset(preset){
  var from=today(),to=today();
  if(preset==='yesterday'){
    from=recentShiftDate(today(),-1);to=from;
  }else if(preset==='this_month'){
    var currentCycle=cycleRange(today());
    from=currentCycle.from;to=currentCycle.to>today()?today():currentCycle.to;
  }else if(preset==='last_month'){
    var thisCycle=cycleRange(today());
    var previousCycle=cycleRange(recentShiftDate(thisCycle.from,-1));
    from=previousCycle.from;to=previousCycle.to;
  }
  var fromEl=_g('rec-from'),toEl=_g('rec-to');
  if(fromEl)fromEl.value=from;
  if(toEl)toEl.value=to;
  renderRecent(1);
}
function renderRecent(page){
  if(page!==undefined&&page!==null)REC_PAGE=Math.max(1,parseInt(page,10)||1);
  _t('rec-scope-badge',scopeName());
  _s('rec-list','<div class="card"><div class="empty"><div class="empty-ic">⏳</div>Loading recent bills…</div></div>');
  var q=(_v('rec-q')||'').trim(), st=_v('rec-status'), f=_v('rec-from'), t=_v('rec-to');
  /* include DRAFTS as well as submitted bills (0 = draft, 1 = submitted) */
  var filters=[['docstatus','in',[0,1]]].concat(scopeFilter('branch'));
  if(st)filters.push(['status','=',st]);
  if(f)filters.push(['posting_date','>=',f]);
  if(t)filters.push(['posting_date','<=',t]);
  getList('Sales Invoice',filters,
    ['name','patient','patient_name','posting_date','branch','grand_total','outstanding_amount',
     'status','docstatus','owner','custom_referring_name','ref_practitioner',
     'custom_remarks_for_office_use'],
    {limit:0, order_by:'posting_date desc, creation desc'})
  .then(function(list){
    list=list||[];
    if(!q)return {list:list,mobileMap:{}};
    var patients=[];
    list.forEach(function(i){if(i.patient&&patients.indexOf(i.patient)<0)patients.push(i.patient);});
    if(!patients.length)return {list:list,mobileMap:{}};
    return getListSilent('Patient',[['name','in',patients]],['name','mobile'],{limit:0})
      .then(function(rows){
        var mobileMap={};
        (rows||[]).forEach(function(p){mobileMap[p.name]=String(p.mobile||'').replace(/\D/g,'');});
        return {list:list,mobileMap:mobileMap};
      })
      .catch(function(){return {list:list,mobileMap:{}};});
  })
  .then(function(ctx){
    var list=ctx.list||[];
    if(q){
      var needle=q.toLowerCase();
      var digits=q.replace(/\D/g,'');
      list=list.filter(function(i){
        var byInvoice=String(i.name||'').toLowerCase().indexOf(needle)>-1;
        var byName=String(i.patient_name||'').toLowerCase().indexOf(needle)>-1;
        var mobile=ctx.mobileMap[i.patient]||'';
        var byMobile=digits.length>0 && mobile.indexOf(digits)>-1;
        return byInvoice||byName||byMobile;
      });
    }
    var totalRecords=list.length;
    var totalPages=Math.max(1,Math.ceil(totalRecords/REC_PER_PAGE));
    if(REC_PAGE>totalPages)REC_PAGE=totalPages;
    var start=(REC_PAGE-1)*REC_PER_PAGE;
    var pageList=list.slice(start,start+REC_PER_PAGE);
    var rows=pageList.map(function(i){
      var isDraft=(i.docstatus===0);
      var badge=isDraft?'bg-amber':((i.outstanding_amount<=0)?'bg-green':(i.outstanding_amount<i.grand_total?'bg-amber':'bg-red'));
      var stLabel=isDraft?'Draft':(i.status||'');
      var bookedBy=i.custom_referring_name||i.owner||'';
      var hasRemarks=!!(i.custom_remarks_for_office_use && String(i.custom_remarks_for_office_use).trim());
      return '<tr data-rowbill="'+esc(i.name)+'" style="cursor:pointer'+(isDraft?';background:#FFFBEB':'')+'">'+
        '<td>'+
          '<b style="color:var(--g0)">'+esc(i.name)+'</b>'+
          (isDraft?'<div style="font-size:11px;color:#B45309;font-weight:800">DRAFT</div>':'')+
          (hasRemarks?'<div title="Has office remarks" style="font-size:10px;color:#92400E;font-weight:800;margin-top:2px">📝 Has remarks</div>':'')+
        '</td>'+
        '<td>'+fmtD(i.posting_date)+'</td>'+
        '<td><b>'+esc(i.patient_name)+'</b></td>'+
        '<td>'+esc(i.branch||'')+'</td>'+
        '<td style="font-size:12.5px">'+esc(bookedBy)+'</td>'+
        '<td class="money">'+fmtM(i.grand_total)+'</td>'+
        '<td class="money" style="color:var(--red)">'+fmtM(i.outstanding_amount)+'</td>'+
        '<td><span class="badge '+badge+'">'+esc(stLabel)+'</span></td>'+
        '<td><div style="display:flex;gap:5px">'+
          '<button class="btn btn-white btn-sm" title="Open bill / approvals" data-bill="'+esc(i.name)+'">📋</button>'+
          '<button class="btn btn-white btn-sm" title="View bill (print format)" data-view="'+esc(i.name)+'">👁</button>'+
          (String(i.posting_date).slice(0,10)===today()
             ? '<button class="btn btn-white btn-sm" title="Download PDF" data-pdf="'+esc(i.name)+'">⬇</button>'
             : '')+
          (!isDraft && i.outstanding_amount>0?'<button class="btn btn-green btn-sm" title="Collect" data-collect="'+esc(i.name)+'">💰</button>':'')+
        '</div></td>'+
      '</tr>';
    }).join('');
    var first=totalRecords?start+1:0;
    var last=Math.min(start+REC_PER_PAGE,totalRecords);
    var pager='';
    if(totalPages>1){
      pager='<div style="display:flex;align-items:center;justify-content:center;gap:7px;flex-wrap:wrap;padding:14px;border-top:1px solid var(--border)">'+
        '<button class="btn btn-white btn-sm" data-rec-page="'+Math.max(1,REC_PAGE-1)+'" '+(REC_PAGE===1?'disabled':'')+'>← Previous</button>';
      var pStart=Math.max(1,REC_PAGE-2),pEnd=Math.min(totalPages,pStart+4);
      pStart=Math.max(1,pEnd-4);
      for(var pn=pStart;pn<=pEnd;pn++){
        pager+='<button class="btn btn-sm '+(pn===REC_PAGE?'btn-green':'btn-white')+'" data-rec-page="'+pn+'">'+pn+'</button>';
      }
      pager+='<button class="btn btn-white btn-sm" data-rec-page="'+Math.min(totalPages,REC_PAGE+1)+'" '+(REC_PAGE===totalPages?'disabled':'')+'>Next →</button>'+
        '<span style="font-size:12px;color:var(--txt3);font-weight:700">Page '+REC_PAGE+' of '+totalPages+'</span></div>';
    }
    _s('rec-list','<div class="card"><div class="card-hdr"><span class="card-title">Showing '+first+'–'+last+' of '+totalRecords+' bill(s) — newest first</span></div>'+
      '<div style="padding:12px 14px;overflow-x:auto"><table class="tbl"><thead><tr><th>Invoice</th><th>Date</th><th>Client</th><th>Branch</th><th>Booked by</th><th>Total</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>'+
      (rows||'')+'</tbody></table>'+(totalRecords?'':'<div class="empty">No bills match the filters</div>')+'</div>'+pager+'</div>');
    _g('rec-list').querySelectorAll('[data-rec-page]').forEach(function(b){
      b.onclick=function(){if(!this.disabled)renderRecent(parseInt(this.getAttribute('data-rec-page'),10)||1);};
    });
    _g('rec-list').querySelectorAll('[data-collect]').forEach(function(b){b.onclick=function(e){e.stopPropagation();openCollect(this.getAttribute('data-collect'));};});
    _g('rec-list').querySelectorAll('[data-bill]').forEach(function(b){b.onclick=function(e){e.stopPropagation();openBill(this.getAttribute('data-bill'));};});
    _g('rec-list').querySelectorAll('[data-view]').forEach(function(b){b.onclick=function(e){e.stopPropagation();viewBill(this.getAttribute('data-view'));};});
    _g('rec-list').querySelectorAll('[data-pdf]').forEach(function(b){b.onclick=function(e){e.stopPropagation();downloadBillPdf(this.getAttribute('data-pdf'));};});
    _g('rec-list').querySelectorAll('[data-rowbill]').forEach(function(tr){
      tr.onclick=function(ev){
        if(ev.target.closest('button')) return;
        openBill(this.getAttribute('data-rowbill'));
      };
    });
  }).catch(function(){ _s('rec-list','<div class="card"><div class="empty">⚠️ Could not load bills</div></div>'); });
}

