var _penOpen={};
function renderPending(){
  _t('pen-scope-badge',scopeName());
  _s('pen-list','<div class="card"><div class="empty"><div class="empty-ic">⏳</div>Loading pending bills…</div></div>');
  var q=(_v('pen-q')||'').trim(), min=parseFloat(_v('pen-min')||0);
  var f=_v('pen-from'), t=_v('pen-to');
  var filters=[['docstatus','=',1],['outstanding_amount','>',0]].concat(scopeFilter('branch'));
  if(min>0)filters.push(['outstanding_amount','>=',min]);
  if(f)filters.push(['posting_date','>=',f]);
  if(t)filters.push(['posting_date','<=',t]);
  if(q)filters.push(['patient_name','like','%'+q+'%']);
  getList('Sales Invoice',filters,
    ['name','patient_name','patient','posting_date','branch','grand_total','outstanding_amount','status'],
    {limit:0, order_by:'posting_date desc'})
  .then(function(list){
    list=list||[];
    var totDue=list.reduce(function(s,i){return s+(i.outstanding_amount||0);},0);
    _s('pen-summary','<b style="color:var(--red)">'+list.length+' pending bill(s)</b> · total due <b class="money" style="color:var(--red)">'+fmtM(totDue)+'</b> · grouped by month'+((f||t)?' · filtered '+(f?fmtD(f):'…')+' → '+(t?fmtD(t):'…'):''));
    _t('pend-n',list.length||'');
    var groups={}; list.forEach(function(i){var k=String(i.posting_date).slice(0,7);(groups[k]=groups[k]||[]).push(i);});
    var keys=Object.keys(groups).sort().reverse();
    _s('pen-list',keys.map(function(k){
      var g=groups[k]; var gd=g.reduce(function(s,i){return s+(i.outstanding_amount||0);},0);
      var open=_penOpen[k]?' open':'';
      var rows=g.map(function(i){
        var age=daysBetween(i.posting_date,today());
        var paid=(i.grand_total||0)-(i.outstanding_amount||0);
        return '<tr><td><b style="color:var(--g0)">'+esc(i.name)+'</b></td><td>'+fmtD(i.posting_date)+'</td>'+
          '<td><b>'+esc(i.patient_name)+'</b><div style="font-size:10px;color:var(--txt4)">'+esc(i.patient||'')+'</div></td><td>'+esc(i.branch||'')+'</td>'+
          '<td class="money">'+fmtM(i.grand_total)+'</td><td class="money" style="color:var(--g1)">'+fmtM(paid)+'</td>'+
          '<td class="money" style="color:var(--red);font-weight:900">'+fmtM(i.outstanding_amount)+'</td>'+
          '<td><span class="badge '+(age>60?'bg-red':age>30?'bg-amber':'bg-grey')+'">'+age+' days</span></td>'+
          '<td><button class="btn btn-green btn-sm" data-collect="'+esc(i.name)+'">💰 Collect</button></td></tr>';
      }).join('');
      return '<div class="mon-grp'+open+'" id="mg-'+esc(k)+'">'+
        '<div class="mon-head" data-k="'+esc(k)+'"><button class="exp-btn chev">▶</button>'+
        '<b style="font-size:14px;color:var(--g0)">📅 '+monthLabel(k+'-01')+'</b>'+
        '<span class="badge bg-red">'+g.length+' pending</span>'+
        '<span style="margin-left:auto;font-size:14px;font-weight:900;color:var(--red)" class="money">Due: '+fmtM(gd)+'</span></div>'+
        '<div class="mon-body"><div style="overflow-x:auto"><table class="tbl"><thead><tr><th>Invoice</th><th>Date</th><th>Client</th><th>Branch</th><th>Total</th><th>Paid</th><th>Due</th><th>Ageing</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></div></div>';
    }).join('')||'<div class="card"><div class="empty"><div class="empty-ic">🎉</div>No pending bills — everything collected!</div></div>');
    _g('pen-list').querySelectorAll('.mon-head').forEach(function(h){h.onclick=function(){toggleMon(this.getAttribute('data-k'));};});
    _g('pen-list').querySelectorAll('[data-collect]').forEach(function(b){b.onclick=function(e){e.stopPropagation();openCollect(this.getAttribute('data-collect'));};});
  }).catch(function(){ _s('pen-list','<div class="card"><div class="empty">⚠️ Could not load pending bills</div></div>'); });
}
function toggleMon(k){ _penOpen[k]=!_penOpen[k]; var el=_g('mg-'+k); if(el)el.classList.toggle('open',_penOpen[k]); }
function togglePendAll(open){ _all('.mon-grp').forEach(function(el){var k=el.id.slice(3);_penOpen[k]=open;el.classList.toggle('open',open);}); }

