        '<td class="money">'+fmtM(r.billed_ex_gst)+'</td>'+
        '<td class="money" style="font-weight:900;color:var(--g1)">'+fmtM(ct)+'</td>'+
        '<td class="money" style="color:var(--g1)">'+fmtM(r.collected_ex_gst)+'</td>'+
        '<td class="money" style="color:var(--red);font-weight:900">'+fmtM(r.outstanding)+'</td>'+
        '<td class="money">'+fmtM(r.billed_gst)+'</td>'+
        '<td class="money">'+fmtM(r.billed_nongst)+'</td></tr>';
    }).join('');
    var totRow='<tr style="background:var(--gbg2);font-weight:900"><td>TOTAL</td>'+
      '<td class="money">'+fmtM(tot.billed_total)+'</td>'+
      '<td class="money">'+fmtM(tot.billed_ex_gst)+'</td>'+
      '<td class="money" style="color:var(--g1)">'+fmtM(tot.collected_total)+'</td>'+
      '<td class="money" style="color:var(--g1)">'+fmtM(tot.collected_ex_gst)+'</td>'+
      '<td class="money" style="color:var(--red)">'+fmtM(tot.outstanding)+'</td>'+
      '<td class="money">'+fmtM(tot.billed_gst)+'</td>'+
      '<td class="money">'+fmtM(tot.billed_nongst)+'</td></tr>';
    _s('colr-list','<div class="card"><div class="card-hdr"><span class="card-title">Branch-wise — Billed vs Collected vs Outstanding</span></div>'+
      '<div style="padding:12px 14px;overflow-x:auto"><table class="tbl"><thead><tr>'+
      '<th>Branch</th><th>Grand Total</th><th>Total (excl. GST)</th>'+
      '<th>Paid Amount</th><th>Paid (excl. GST)</th><th>Outstanding</th>'+
      '<th>Billed · GST</th><th>Billed · Non-GST</th>'+
      '</tr></thead><tbody>'+trs+totRow+'</tbody></table></div></div>');
  }).catch(function(e){
    _s('colr-list','<div class="card"><div class="empty">⚠️ Could not load the collections report.<br>'+
      '<span style="font-size:11px">This needs a Server Script named <b>lifescc.billing.collections_report</b> '+
      '(whitelisted API method) on the Frappe side.</span><br>'+
      '<span style="font-size:10.5px;color:var(--txt4)">'+esc(e&&e.message||'')+'</span></div></div>');
  });
}

