      '</div>'+
    '</div>';

  document.body.appendChild(overlay);

  var secondsLeft=10;
  var countdown=document.getElementById("life-stock-lock-countdown");
  var closeButton=document.getElementById("life-stock-warning-close-btn");

  if(closeButton){
    closeButton.disabled=true;
    closeButton.textContent="Close ("+secondsLeft+")";
    closeButton.style.cursor="not-allowed";
    closeButton.style.opacity=".7";
  }

  LIFE_STOCK_RECEIPT_GATE_TIMER=setInterval(function(){
    secondsLeft-=1;

    if(countdown){
      countdown.textContent=String(Math.max(0,secondsLeft));
    }

    if(closeButton){
      closeButton.textContent=
        secondsLeft>0
          ? "Close ("+secondsLeft+")"
          : "Close";
    }

    if(secondsLeft<=0){
      clearInterval(LIFE_STOCK_RECEIPT_GATE_TIMER);
      LIFE_STOCK_RECEIPT_GATE_TIMER=null;

      /*
       * Do NOT auto-close.
       * After the mandatory 10-second warning period,
       * enable the Close button and leave the modal visible.
       */
      if(closeButton){
