              '<div class="kpi" style="padding:10px"><div class="kpi-lbl">Already approved</div><div style="font-size:18px;font-weight:900">'+approvedPct+'%</div></div>'+
              '<div class="kpi" style="padding:10px"><div class="kpi-lbl">New request</div><div id="v22-pct" style="font-size:18px;font-weight:900">0%</div></div>'+
              '<div class="kpi" style="padding:10px"><div class="kpi-lbl">Final if approved</div><div id="v22-final-kpi" style="font-size:18px;font-weight:900;color:var(--g1)">'+v22Money(orig)+'</div></div>'+ 
            '</div>'+
            v22LevelRow('L1','Branch Level',used.L1)+
