              used.L1 && used.L2 && used.L3
                ? '<div style="padding:10px 12px;margin:0 0 10px;border-radius:9px;background:#F0FDF4;border:1px solid #A7E3C4;color:var(--g1);font-weight:800">✅ L1, L2 and L3 already have Pending / Approved requests. No additional L1/L2/L3 request can be raised.</div>'
                : ''
            )+
            '<div style="display:flex;gap:18px;align-items:center;padding:11px 13px;border-radius:9px;background:var(--gbg2);border:1px solid var(--border2);margin:10px 0;flex-wrap:wrap"><b id="v22-selected">0 selected</b><span>New discount: <b id="v22-disc" style="color:var(--red)">₹0.00</b></span><span>Combined: <b id="v22-combined">'+approvedPct+'%</b></span><span>Final payable incl GST: <b id="v22-final" style="color:var(--g1)">'+v22Money(orig)+'</b></span></div>'+
            '<div id="v22-warn" style="display:none;padding:9px;color:var(--red);background:var(--red-bg);border:1px solid var(--red-bd);border-radius:8px;margin-bottom:9px"></div>'+
            '<label class="f-lbl">Reason for all selected requests <span class="req">*</span></label><textarea class="f-inp" id="v22-reason" rows="3" style="height:76px" placeholder="Enter the discount reason"></textarea>'+
          '</div>'+
          '<div id="v22-l4" style="display:none">'+
            '<div style="padding:12px;background:var(--purple-bg);border:1px solid var(--purple-bd);border-radius:10px;margin-bottom:12px">Use L4 separately for an exact customer payable amount. Do not combine L4 with pending L1/L2/L3 requests.</div>'+
            '<div class="grid2"><div><label class="f-lbl">L4 Approver <span class="req">*</span></label><select class="f-sel" id="v22-l4-user">'+v22Options('L4')+'</select></div><div><label class="f-lbl">Final payable including GST ₹ <span class="req">*</span></label><input class="f-inp" id="v22-l4-final" type="number" min="1" oninput="lifeV22L4Calc()"></div></div>'+
            '<div id="v22-l4-calc" style="margin:12px 0;padding:11px;background:var(--gbg2);border:1px solid var(--border2);border-radius:9px"></div>'+
            '<label class="f-lbl">Reason <span class="req">*</span></label><textarea class="f-inp" id="v22-l4-reason" rows="3" style="height:76px"></textarea>'+
          '</div>'+
          '<div id="v22-error" style="display:none;margin-top:10px;padding:10px;border-radius:8px;background:var(--red-bg);border:1px solid var(--red-bd);color:var(--red)"></div>'+
          '<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px"><button class="btn btn-white" onclick="lifeV22CloseDiscount()">Cancel</button><button class="btn btn-green" id="v22-submit" onclick="lifeV22Submit(\''+esc(inv)+'\')">🔐 Send selected requests</button></div>'+
        '</div></div></div>';
    document.body.insertAdjacentHTML('beforeend',html);
    v22Recalc(); lifeV22L4Calc();
  }

  window.lifeV22Submit=function(inv){
    var root=document.getElementById('life-v22-discount-modal');
    var mode=root?root.getAttribute('data-mode'):'normal';
    var err=document.getElementById('v22-error');
    function bad(msg){if(err){err.textContent=msg;err.style.display='block';}return;}
    if(err)err.style.display='none';
    var btn=document.getElementById('v22-submit'),restore=btnBusy(btn,'Sending…');
    var promise;
    if(mode==='l4'){
      var user=(_v('v22-l4-user')||'').trim(),finalAmount=parseFloat(_v('v22-l4-final')||0),reason=(_v('v22-l4-reason')||'').trim();
      var current=parseFloat(root.getAttribute('data-current')||0);
      if(!user){if(restore)restore();return bad('Select the L4 approver.');}
      if(!(finalAmount>0)||finalAmount>=current){if(restore)restore();return bad('Final amount must be greater than zero and less than '+v22Money(current)+'.');}
      if(!reason){if(restore)restore();return bad('Enter the L4 reason.');}
      promise=call('create_discount_approval_request',{invoice_name:inv,selected_approver:user,approval_level:'L4',requested_discount_pct:0,requested_final_amount:finalAmount,reason:reason});
    }else{

      var rows=[];
      var total=0;
      var reason=(_v('v22-reason')||'').trim();

      ['L1','L2','L3'].forEach(function(level){

        var on=
          document.getElementById(
            'v22-on-'+level
          );

        if(on && on.checked){

          var user=
            (_v('v22-user-'+level)||'')
              .trim();

          var pct=
            parseFloat(
              _v('v22-pct-'+level)||0
            );

          rows.push({
            approval_level:level,
            selected_approver:user,
            requested_discount_pct:pct,
            reason:reason
          });

          total+=pct||0;
        }
      });


      if(!rows.length){
        if(restore)restore();
        return bad(
          'Select at least one available approval level.'
        );
      }


      for(var i=0;i<rows.length;i++){

        if(!rows[i].selected_approver){
          if(restore)restore();
          return bad(
            'Select the '+
            rows[i].approval_level+
            ' approver.'
          );
        }

        if(
          !(rows[i].requested_discount_pct>=0.5) ||
          rows[i].requested_discount_pct>5
        ){
          if(restore)restore();
          return bad(
            rows[i].approval_level+
            ' must be between 0.5% and 5%.'
          );
        }
      }


      if(!reason){
        if(restore)restore();
        return bad(
          'Enter the discount reason.'
        );
      }


      /*
       * Do not trust only the state captured when the modal opened.
       * Reload the complete approval chain immediately before creating
       * requests. This prevents L2/L3 duplicates when another approver
       * has acted, or when browser permissions hide sibling rows.
       */
      promise=
        lifeLoadInvoiceDiscountRequests(
          inv
        )

        .then(function(latestRows){

          latestRows=
            latestRows||[];

          var used={};
          var approvedLatest=0;

          latestRows.forEach(
            function(r){

              var level=
                String(
                  r.approval_level||''
                ).trim();

              if(
                level &&
                (
                  r.status==='Pending' ||
                  r.status==='Approved'
                )
              ){
                used[level]=true;
              }

              if(
                r.status==='Approved' &&
                (
                  level==='L1' ||
                  level==='L2' ||
                  level==='L3'
                )
              ){
                approvedLatest+=
                  parseFloat(
                    r.approved_discount_pct ||
                    r.requested_discount_pct ||
                    0
                  ) || 0;
              }
            }
          );


          /*
           * Every selected level must still be unused.
           */
          for(
            var j=0;
            j<rows.length;
            j++
          ){

            var selectedLevel=
              rows[j].approval_level;

            if(used[selectedLevel]){

              throw new Error(
                selectedLevel+
                ' already has a Pending or Approved discount request. '+
                'Refresh the bill and choose only an available level.'
              );
            }
          }


          /*
           * L1 + L2 + L3 cumulative hard cap = 15%.
           * Existing approved percentage + this new batch may not exceed 15%.
           */
          var combined=
            approvedLatest+
            total;

          if(combined>15.000001){

            throw new Error(
              'Combined L1 + L2 + L3 discount cannot exceed 15%. '+
              'Already approved: '+
              approvedLatest.toFixed(2).replace(/\.00$/,'')+
              '%. New request: '+
              total.toFixed(2).replace(/\.00$/,'')+
              '%.'
            );
          }


          return call(
            'create_multiple_discount_approval_requests_v2',
            {
              invoice_name:inv,
              requests:JSON.stringify(
                rows
              )
            }
          );
        });
    }
    promise.then(function(res){
      if(restore)restore();
      v22Close();
      alertMsg(mode==='l4'?'L4 discount request sent successfully.':((res&&res.count)||'Selected')+' discount requests sent successfully.','green',true);
      updateApprBadge();renderApprovals();openBill(inv);
    }).catch(function(e){if(restore)restore();bad(serverErr(e));});
  };

  window.requestNextApproval=function(inv){

    if(!inv){
      return;
    }

    /*
     * IMPORTANT:
     * Use the exact same complete approval loader as the Bill drawer.
     * A direct browser-side getList can hide L2/L3 rows for branch users,
     * which previously made already-approved levels selectable again.
     */
    Promise.all([
      getDoc(
        'Sales Invoice',
        inv
      ),
      lifeLoadInvoiceDiscountRequests(
        inv
      )
    ])

    .then(function(all){

      var si=all[0];
      var reqs=all[1]||[];

      if(!si || si.docstatus!==0){
        alertMsg(
          'Discount can only be requested while the invoice is Draft.',
          'red'
        );
        return;
      }

      v22Open(
        inv,
        si,
        reqs
      );
    })

    .catch(function(e){
      alertMsg(
        'Could not open discount request: '+
        serverErr(e),
        'red'
      );
    });
  };
})();


/* LIFE Billing v23 — fixes skipped approval creation and adds live calculations */
(function(){
  var v23PreviousPayload=billPayload;

  billPayload=function(){
    var payload=v23PreviousPayload.apply(this,arguments);
    var discountOn=_g('bl-disc-on')&&_g('bl-disc-on').checked;
    var selected=false;
    ['L1','L2','L3'].forEach(function(level){
      var on=_g('v21-on-'+level);
      if(on&&on.checked)selected=true;
    });
    if(discountOn&&selected){
      /* Critical v23 fix: confirmGenerate() checks this value before deciding
         whether it should call the multiple-request API. */
      payload.draft_only=1;
    }
    return payload;
  };

  window.lifeV21UpdateSummary=function(){
    var totalPct=0,count=0;
    ['L1','L2','L3'].forEach(function(level){
      var on=_g('v21-on-'+level);
      if(on&&on.checked){
        var pct=parseFloat(_v('v21-pct-'+level)||0);
        if(pct>0){totalPct+=pct;count++;}
      }
    });

    var totals=(BILL&&BILL._totals)||{};
    var subtotal=parseFloat(totals.sub||0);
    var gst=parseFloat(totals.gst||0);
    var grand=parseFloat(totals.total||0);
    if(!(grand>0)){
      grand=Math.round((subtotal+gst)*100)/100;
    }

    /* All approval percentages are calculated on Grand Total including GST. */
    var discount=Math.round(grand*totalPct)/100;
    var finalPayable=Math.round((grand-discount)*100)/100;
    var valid=totalPct<=15;

    var box=_g('v21-summary');
    if(box){
      box.innerHTML=
        '<div style="display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:8px">'+
          '<div style="padding:9px;background:#fff;border:1px solid var(--border);border-radius:8px"><div style="font-size:10px;color:var(--txt3);font-weight:800">ORIGINAL INCL GST</div><b style="font-size:16px">'+fmtM(grand)+'</b></div>'+
          '<div style="padding:9px;background:#fff;border:1px solid var(--border);border-radius:8px"><div style="font-size:10px;color:var(--txt3);font-weight:800">SELECTED</div><b style="font-size:16px">'+count+' level'+(count===1?'':'s')+' · '+totalPct+'%</b></div>'+
          '<div style="padding:9px;background:var(--red-bg);border:1px solid var(--red-bd);border-radius:8px"><div style="font-size:10px;color:var(--red);font-weight:800">DISCOUNT AMOUNT</div><b style="font-size:16px;color:var(--red)">− '+fmtM(discount)+'</b></div>'+
          '<div style="padding:9px;background:#ECFDF5;border:1px solid #A7E3C4;border-radius:8px"><div style="font-size:10px;color:var(--g1);font-weight:800">FINAL PAYABLE INCL GST</div><b style="font-size:16px;color:var(--g1)">'+fmtM(finalPayable)+'</b></div>'+
        '</div>'+
        '<div style="font-size:11.5px;margin-top:7px;color:'+(valid?'var(--g1)':'var(--red)')+'">'+
          (valid
            ? count+' approval request'+(count===1?'':'s')+' will be created together. Each percentage uses the original GST-inclusive total.'
            : 'Combined L1 + L2 + L3 discount cannot exceed 15%.')+
        '</div>';
    }

    var brk=_g('bl-brk');
    if(brk){
      var preview=_g('v23-disc-preview');
      if(!preview){
        preview=document.createElement('div');
        preview.id='v23-disc-preview';
        brk.parentNode.insertBefore(preview,brk.nextSibling);
      }
      /*
       * Keep the empty discount hint extremely compact so the action
       * buttons remain visible beside the subtotal card.
       * Once a level is selected, restore the normal calculation box.
       */
      if(count){
        preview.style.cssText=
          'margin:6px 0;padding:8px 10px;border-radius:9px;background:#fff;'+
          'border:1.5px solid '+(valid?'#A7E3C4':'var(--red-bd)')+';font-size:12px';

        preview.innerHTML=
          '<div style="display:flex;justify-content:space-between;gap:8px;margin-bottom:4px">'+
            '<span>Requested discount ('+totalPct+'%)</span>'+
            '<b style="color:var(--red)">− '+fmtM(discount)+'</b>'+
          '</div>'+
          '<div style="display:flex;justify-content:space-between;gap:8px;font-size:13px">'+
            '<b>Final payable incl GST</b>'+
            '<b style="color:var(--g1)">'+fmtM(finalPayable)+'</b>'+
          '</div>';
      }else{
        preview.style.cssText=
          'margin:2px 0 3px;padding:0;border:0;background:transparent;'+
          'border-radius:0;box-shadow:none;font-size:10.5px;line-height:1.25;'+
          'color:var(--txt3);';

        preview.innerHTML=
          'Select L1, L2 or L3 to see the discount calculation.';
      }
    }
  };

  /* Repaint whenever the page recalculates therapy totals, without causing a
     recalc loop. */
  var v23PreviousRecalc=recalc;
  recalc=function(){
    var result=v23PreviousRecalc.apply(this,arguments);
    setTimeout(function(){try{lifeV21UpdateSummary();}catch(e){}},0);
    return result;
  };
})();


/* LIFE Billing v24 — live recording + existing video upload */
(function () {
  var MAX_LOAN_VIDEO_BYTES = 100 * 1024 * 1024;
  var MAX_LOAN_VIDEO_SECONDS = 120;

  function loanVideoSourceLabel(video) {
    return video && video.source === "upload"
      ? "Video uploaded & verified"
      : "Video recorded & verified";
  }

  loanVideoRowHtml = function (i) {
    var video = LOAN_VIDEO[i];

    if (video && video.url) {
      return '' +
        '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">' +
          '<span style="color:var(--g1);font-weight:800;font-size:12.5px">✅ ' +
            esc(loanVideoSourceLabel(video)) +
          '</span>' +
          '<a href="' + esc(video.url) + '" target="_blank" rel="noopener" class="btn btn-white btn-sm">▶ View</a>' +
          '<button type="button" class="btn btn-white btn-sm" onclick="startLoanVideo(' + i + ')">🎥 Re-record</button>' +
          '<button type="button" class="btn btn-white btn-sm" onclick="lifeChooseLoanVideo(' + i + ')">⬆ Replace upload</button>' +
          '<button type="button" class="btn btn-white btn-sm" style="color:var(--red)" onclick="lifeRemoveLoanVideo(' + i + ')">✕ Remove</button>' +
          '<input type="file" id="life-loan-upload-' + i + '" accept="video/mp4,video/webm,video/quicktime,video/x-m4v,.mp4,.webm,.mov,.m4v" style="display:none" onchange="lifeSelectLoanVideo(' + i + ',this)">' +
        '</div>';
    }

    return '' +
      '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">' +
        '<button type="button" class="btn btn-green btn-sm" onclick="startLoanVideo(' + i + ')">🎥 Record Live Video</button>' +
        '<button type="button" class="btn btn-white btn-sm" onclick="lifeChooseLoanVideo(' + i + ')">⬆ Upload Video</button>' +
        '<input type="file" id="life-loan-upload-' + i + '" accept="video/mp4,video/webm,video/quicktime,video/x-m4v,.mp4,.webm,.mov,.m4v" style="display:none" onchange="lifeSelectLoanVideo(' + i + ',this)">' +
        '<span style="font-size:11.5px;color:var(--txt3)">Maximum 2 minutes · MP4, WebM, MOV or M4V</span>' +
      '</div>';
  };

  onLoanVideoSaved = function (i, url, source) {
    LOAN_VIDEO[i] = {
      url: url,
      verified: true,
      source: source || "record"
    };
    refreshLoanVideoRow(i);
  };

  window.lifeChooseLoanVideo = function (i) {
    var input = _g("life-loan-upload-" + i);
    if (!input) {
      refreshLoanVideoRow(i);
      input = _g("life-loan-upload-" + i);
    }
    if (input) {
      input.value = "";
      input.click();
    }
  };

  window.lifeRemoveLoanVideo = function (i) {
    if (!LOAN_VIDEO[i]) return;

    if (window.frappe && frappe.confirm) {
      frappe.confirm(
        "Remove this loan declaration video?",
        function () {
          delete LOAN_VIDEO[i];
          refreshLoanVideoRow(i);
          frappe.show_alert({
            message: "Loan declaration video removed.",
            indicator: "orange"
          }, 4);
        }
      );
      return;
    }

    if (window.confirm("Remove this loan declaration video?")) {
      delete LOAN_VIDEO[i];
      refreshLoanVideoRow(i);
    }
  };

  window.lifeSelectLoanVideo = function (i, input) {
    var file = input && input.files && input.files[0];
    if (!file) return;

    var fileName = String(file.name || "");
    var allowedExtension = /\.(mp4|webm|mov|m4v)$/i.test(fileName);
    var allowedMime = !file.type || /^video\//i.test(file.type);

    if (!allowedExtension || !allowedMime) {
      input.value = "";
      alertMsg("Select an MP4, WebM, MOV or M4V video file.", "red");
      return;
    }

    if (file.size > MAX_LOAN_VIDEO_BYTES) {
      input.value = "";
      alertMsg("Video must not exceed 100 MB.", "red");
      return;
    }

    var objectUrl = URL.createObjectURL(file);
    var probe = document.createElement("video");
    probe.preload = "metadata";
    probe.muted = true;
    probe.playsInline = true;

    var finished = false;
    function cleanupProbe() {
      if (finished) return;
      finished = true;
      probe.removeAttribute("src");
      try { probe.load(); } catch (e) {}
    }

    probe.onloadedmetadata = function () {
      var duration = Number(probe.duration || 0);
      cleanupProbe();

      if (!duration || !isFinite(duration)) {
        URL.revokeObjectURL(objectUrl);
        input.value = "";
        alertMsg("Could not read this video. Please use MP4 or WebM.", "red");
        return;
      }

      if (duration > MAX_LOAN_VIDEO_SECONDS + 0.5) {
        URL.revokeObjectURL(objectUrl);
        input.value = "";
        alertMsg("Loan declaration video must be 2 minutes or shorter.", "red");
        return;
      }

      lifeShowUploadedVideoReview(i, file, objectUrl, duration, input);
    };

    probe.onerror = function () {
      cleanupProbe();
      URL.revokeObjectURL(objectUrl);
      input.value = "";
      alertMsg("This video cannot be previewed. Please upload MP4 or WebM.", "red");
    };

    probe.src = objectUrl;
  };

  window.lifeShowUploadedVideoReview = function (i, file, objectUrl, duration, input) {
    var modalId = "life-upload-video-review";
    $("#" + modalId).remove();

    var mins = Math.floor(duration / 60);
    var secs = Math.round(duration % 60);
    var durationText = mins + ":" + String(secs).padStart(2, "0");
    var sizeText = (file.size / 1024 / 1024).toFixed(1) + " MB";

    $("body").append(
      '<div id="' + modalId + '" style="position:fixed;inset:0;background:rgba(0,0,0,.82);z-index:100000;display:flex;align-items:center;justify-content:center;padding:16px">' +
        '<div style="background:#fff;border-radius:16px;padding:20px;width:620px;max-width:96vw;max-height:94vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.35)">' +
          '<div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:12px">' +
            '<div><div style="font-size:18px;font-weight:900;color:var(--g0)">⬆ Verify Uploaded Loan Video</div>' +
            '<div style="font-size:12px;color:var(--txt3);margin-top:3px">' + esc(file.name) + ' · ' + durationText + ' · ' + sizeText + '</div></div>' +
            '<button type="button" id="life-upload-close" style="margin-left:auto;border:0;background:#eef2ef;border-radius:50%;width:32px;height:32px">✕</button>' +
          '</div>' +
          '<video controls playsinline preload="metadata" src="' + esc(objectUrl) + '" style="display:block;width:100%;max-height:360px;background:#111;border-radius:10px"></video>' +
          '<label style="display:flex;align-items:flex-start;gap:10px;margin-top:14px;padding:12px;border:1.5px solid #A7E3C4;background:#ECFDF5;border-radius:10px;cursor:pointer">' +
            '<input type="checkbox" id="life-upload-confirmed" style="width:18px;height:18px;margin-top:1px">' +
            '<span style="font-size:12.5px;color:var(--g0);font-weight:700">I watched and verified that the client is visible and clearly gives the loan declaration.</span>' +
          '</label>' +
          '<div id="life-upload-error" style="display:none;margin-top:10px;color:var(--red);font-size:12px;font-weight:700"></div>' +
