        document.getElementById(
            "life-email-reject"
        ).onclick = function () {

            setExactGlobals();

            billReject(
                directRequest.name
            );
        };
    }


    function openExactBill(
        invoiceName,
        requestName
    ) {

        showLoader();

        /*
         * First load the exact approval request.
         */
        /*
         * Resolve the authenticated ERPNext user directly from
         * the server before checking the selected approver.
         */
        call(
            "frappe.auth.get_logged_user",
            {}
        )

        .then(function (authenticatedUser) {

            var resolvedUser = "";

            if (
                typeof authenticatedUser === "string"
            ) {
                resolvedUser =
                    authenticatedUser;
            }

            else if (
                authenticatedUser &&
                authenticatedUser.user
            ) {
                resolvedUser =
                    authenticatedUser.user;
            }

            else if (
                authenticatedUser &&
                authenticatedUser.message
            ) {
                resolvedUser =
                    authenticatedUser.message;
            }

            resolvedUser = String(
                resolvedUser || ""
            ).trim();

            if (
                !resolvedUser ||
                resolvedUser === "Guest"
            ) {
                throw new Error(
                    "Your ERP login session could not be verified. " +
                    "Please sign in again."
                );
            }

            CURRENT_USER =
                resolvedUser;

            return getDoc(
                "Discount Approval Request",
                requestName
            );
        })

        .then(function (request) {

            if (!request) {
                throw new Error(
                    "Approval request was not found."
                );
            }

            if (
                request.linked_invoice !==
                invoiceName
            ) {
                throw new Error(
                    "Approval request and invoice do not match."
                );
            }

            if (
                request.status !== "Pending"
            ) {
                throw new Error(
                    "This request is already " +
                    request.status +
                    "."
                );
            }

            if (!isAuthorized(request)) {
                throw new Error(
                    "You are not the selected approver."
                );
            }

            directRequest =
                request;

            return getDoc(
                "Sales Invoice",
                invoiceName
            );
        })

        .then(function (invoiceDocument) {

            directInvoiceDoc =
                invoiceDocument || {
                    name:invoiceName
                };

            setExactGlobals();

            document.documentElement.classList.add(
                "life-email-bill-mode"
            );

            /*
             * Open exact bill directly.
             * Do not open the Discount Approvals list.
             */
            openBill(invoiceName);

            setTimeout(function () {

                /*
                 * openBill loads all approval history.
                 * Reset action variables to exact email request.
                 */
                setExactGlobals();

                removeElement(
                    "life-email-bill-loader"
                );

                renderActionBar();

                var billModal =
                    _g("m-bill");

                if (billModal) {
                    var modalBody =
                        billModal.querySelector(
                            ".m-body"
                        );

                    if (modalBody) {
                        modalBody.scrollTop = 0;
                    }
                }

            }, 900);
        })

        .catch(function (error) {

            document.documentElement.classList.remove(
                "life-email-bill-mode"
            );

            var message =
                error &&
                error.message
                    ? error.message
                    : serverErr(error);

            showError(message);
        });
    }


    function startDirectEmailBill() {

        if (directStarted) {
            return true;
        }

        var parameters =
            getEmailParameters();

        if (
            !parameters.invoice ||
            !parameters.request
        ) {
            return false;
        }

        if (
            typeof getDoc !== "function" ||
            typeof openBill !== "function" ||
            typeof billApprove !== "function" ||
            typeof billReject !== "function" ||
            typeof CURRENT_USER === "undefined" ||
            !CURRENT_USER ||
            CURRENT_USER === "Guest"
        ) {
            return false;
        }

        directStarted = true;

        directInvoice =
            parameters.invoice;

        openExactBill(
            parameters.invoice,
            parameters.request
        );

        return true;
    }


    /*
     * Show loader early when this URL is from an approval email.
     */
    var initialParameters =
        getEmailParameters();

    if (
        initialParameters.invoice &&
        initialParameters.request
    ) {
        if (document.body) {
            showLoader();
        } else {
            document.addEventListener(
                "DOMContentLoaded",
                showLoader
            );
        }
    }


    /*
     * Wait until the Billing module finishes loading.
     */
    var attempts = 0;

    var startTimer =
        setInterval(function () {

            attempts += 1;

            if (startDirectEmailBill()) {
                clearInterval(
                    startTimer
                );
            }

            if (attempts >= 160) {

                clearInterval(
                    startTimer
                );

                if (!directStarted) {
                    removeElement(
                        "life-email-bill-loader"
                    );
                }
            }

        }, 250);

})();

(function () {

    if (window.__lifeBillingUrlSyncV10) {
        return;
    }

    window.__lifeBillingUrlSyncV10 = true;


    function getTargetWindow() {

        try {
            if (
                window.parent &&
                window.parent !== window &&
                window.parent.history &&
                window.parent.location
            ) {
                return window.parent;
            }
        } catch (error) {}

        return window;
    }


    function cleanViewName(viewName) {

        var allowed = [
            "billing",
            "recent",
            "pending",
            "collections",
            "approvals"
        ];

        if (
            allowed.indexOf(viewName) < 0
        ) {
            return "billing";
        }

        return viewName;
    }


    function updatePortalUrl(viewName) {

        viewName =
            cleanViewName(viewName);

        var targetWindow =
            getTargetWindow();

        var targetPath;

        /*
         * Billing inside life-home:
         * update the parent portal URL.
         */
        if (
            targetWindow.location.pathname
                .indexOf("/life-home") >= 0
        ) {
            targetPath =
                "/life-home" +
                "?view=billing" +
                "&billing_view=" +
                encodeURIComponent(viewName);
        }

        /*
         * Direct billing-v2:
         * keep billing-v2 as the route.
         */
        else {
            targetPath =
                "/billing-v2" +
                "?view=" +
                encodeURIComponent(viewName);
        }

        /*
         * invoice and request parameters are intentionally removed.
         */
        targetWindow.history.replaceState(
            {
                lifeBillingView:viewName
            },
            "",
            targetPath
        );
    }


    function currentBillingView() {

        if (
            typeof ACTIVE_VIEW !== "undefined" &&
            ACTIVE_VIEW
        ) {
            return cleanViewName(
                ACTIVE_VIEW
            );
        }

        var activeButton =
            document.querySelector(
                ".nav-pill.active[data-v]"
            );

        if (activeButton) {
            return cleanViewName(
                activeButton.getAttribute(
                    "data-v"
                )
            );
        }

        return "billing";
    }


    function bindTabUrlUpdates() {

        var buttons =
            document.querySelectorAll(
                ".nav-pill[data-v]"
            );

        Array.prototype.forEach.call(
            buttons,
            function (button) {

                if (
                    button.getAttribute(
                        "data-life-url-bound"
                    ) === "1"
                ) {
                    return;
                }

                button.setAttribute(
                    "data-life-url-bound",
                    "1"
                );

                button.addEventListener(
                    "click",
                    function () {

                        var selectedView =
                            button.getAttribute(
                                "data-v"
                            ) || "billing";

                        /*
                         * Let the existing showView() finish first.
                         */
                        setTimeout(function () {
                            updatePortalUrl(
                                selectedView
                            );
                        }, 30);
                    }
                );
            }
        );
    }


    function emailParametersExist() {

        var locations = [];

        try {
            locations.push(
                window.location.search || ""
            );
        } catch (error) {}

        try {
            if (
                window.parent &&
                window.parent !== window
            ) {
                locations.push(
                    window.parent.location.search || ""
                );
            }
        } catch (error) {}

        var combined =
            locations.join("&");

        return (
            combined.indexOf("invoice=") >= 0 &&
            combined.indexOf("request=") >= 0
        );
    }


    function cleanUrlAfterBillOpens() {

        if (!emailParametersExist()) {
            return;
        }

        var attempts = 0;

        var modalTimer =
            setInterval(function () {

                attempts += 1;

                var billModal =
                    document.getElementById(
                        "m-bill"
                    );

                var modalOpen = false;

                if (billModal) {
                    modalOpen = (
                        billModal.classList.contains(
                            "show"
                        ) ||
                        window.getComputedStyle(
                            billModal
                        ).display !== "none"
                    );
                }

                if (modalOpen) {

                    clearInterval(
                        modalTimer
                    );

                    /*
                     * The exact bill is already open.
                     * The email parameters are no longer needed.
                     */
                    updatePortalUrl(
                        currentBillingView()
                    );
                }

                if (attempts >= 100) {
                    clearInterval(
                        modalTimer
                    );
                }

            }, 200);
    }


    function startUrlSync() {

        bindTabUrlUpdates();
        cleanUrlAfterBillOpens();

        /*
         * Rebind if the navigation is rendered again.
         */
        var observer =
            new MutationObserver(function () {
                bindTabUrlUpdates();
            });

        observer.observe(
            document.body,
            {
                childList:true,
                subtree:true
            }
        );
    }


    if (document.body) {
        startUrlSync();
    } else {
        document.addEventListener(
            "DOMContentLoaded",
            startUrlSync
        );
    }

})();

